/* Apple DNA — pure white, huge tight display type, monochrome with one blue accent */
.theme-apple-dna {
  --bg: oklch(1 0 0);
  --surface: oklch(0.971 0.003 286.4);
  --surface-2: oklch(0.955 0 0);
  --fg: oklch(0.232 0.004 286.1);
  --fg-muted: oklch(0.622 0.007 286.2);
  --accent: oklch(0.563 0.193 256.2);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.669 0.181 251.8);
  --line: oklch(0.9 0 0);
  --success: oklch(0.66 0.16 150);
  --warning: oklch(0.8 0.15 80);
  --danger: oklch(0.6 0.22 25);

  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0 0 0 / 5%);
  --shadow-2: 0 8px 24px -8px oklch(0 0 0 / 12%);
  --shadow-3: 0 30px 70px -30px oklch(0 0 0 / 25%);
  --glow: 0 0 0 4px color-mix(in oklab, var(--accent) 25%, transparent);

  --border-width: 1px;
  --blur-amount: 20px;

  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", sans-serif;
  --font-body: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.045em;
  --label-transform: none;
  --label-tracking: 0em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-apple-dna h1,
.theme-apple-dna h2,
.theme-apple-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
  line-height: 1.03;
}

.theme-apple-dna h1 {
  font-size: clamp(3rem, 7vw, 5.5rem);
}

.theme-apple-dna button {
  border-radius: var(--radius-pill);
  font-weight: 500;
}

/* signature */
.theme-apple-dna h1 { font-weight: 700; }
.theme-apple-dna button { font-size: 0.95em; }
.theme-apple-dna ::selection { background: oklch(0.7 0.15 255 / 30%); }

/* alt mode: auto-derived dark variant */
.theme-apple-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
